/**
 * Core domain types for the log-analysis engine.
 * DO NOT EDIT this file without explicit instruction.
 */

// ─── Raw event ───────────────────────────────────────────────────────────────

export interface LogEvent {
  /** Stable deduplication key (hash of rawRow). */
  id: string;
  /** ISO 8601 UTC timestamp, e.g. "2024-03-15T14:23:01Z". */
  timestamp: string;
  username: string;
  sourceIp: string;
  host: string;
  eventType: string;
  result: string;
  /** Windows logon type code as a string, e.g. "3", or null if missing. */
  logonType: string | null;
  /** Original CSV row exactly as parsed. */
  rawRow: string;
  /** Analyst flags attached during analysis, e.g. ["off-hours", "privileged"]. */
  flags: string[];
}

// ─── Alert ───────────────────────────────────────────────────────────────────

export type Severity = "low" | "medium" | "high" | "critical";

export interface Alert {
  id: string;
  ruleId: string;
  username: string;
  /** ISO 8601 UTC – start of the event window that triggered this alert. */
  timeStart: string;
  /** ISO 8601 UTC – end of the event window that triggered this alert. */
  timeEnd: string;
  severity: Severity;
  /** IDs of LogEvents that constitute the evidence for this alert. */
  evidenceIds: string[];
  /** Plain-language description of what the rule detected. */
  explanation: string;
  /** Rule-specific structured data (thresholds hit, counts, etc.). */
  details: Record<string, unknown>;
}

// ─── Incident ─────────────────────────────────────────────────────────────────

export interface ScoreBreakdownEntry {
  label: string;
  points: number;
}

export interface Incident {
  id: string;
  username: string;
  alerts: Alert[];
  /** Composite risk score 0–100. */
  score: number;
  severity: Severity;
  /** Human-readable summary of why this incident is suspicious. */
  explanation: string;
  scoreBreakdown: ScoreBreakdownEntry[];
  /** Ordered triage checklist an analyst should follow. */
  triageSteps: string[];
  /**
   * Fixed disposition label.
   * Findings are "suspicious indications" – never "confirmed compromise".
   */
  disposition: "suspicious";
}

// ─── Ingest report ───────────────────────────────────────────────────────────

export interface InvalidRow {
  row: string;
  reason: string;
}

export interface ParseReport {
  totalRows: number;
  validRows: number;
  rejectedCount: number;
  rejectedByReason: Record<string, number>;
  invalidRows: InvalidRow[];
}

export interface IngestReport {
  totalRows: number;
  validRows: number;
  invalidRows: InvalidRow[];
  duplicatesRemoved: number;
  missingFieldCounts: Record<string, number>;
  rejectedByReason?: Record<string, number>;
  parseReport?: ParseReport;
}

// ─── Config ──────────────────────────────────────────────────────────────────

export interface TimeWindow {
  start: string; // ISO 8601
  end: string;   // ISO 8601
}

export interface AssetEntry {
  host: string;
  role: string;
  privileged?: boolean;
}

export interface IpLocationEntry {
  cidr: string;
  location: string;
}

export interface Config {
  thresholds: Record<string, number>;
  /** The period used to learn baselines. Events outside this window are excluded from baseline calculations. */
  trainingPeriod: TimeWindow;
  /** IANA timezone string, e.g. "America/New_York". */
  timezone: string;
  maintenanceWindows: TimeWindow[];
  /** Accounts whose activity is considered pre-approved and should reduce severity. */
  approvedAccounts: string[];
  /** CIDR ranges that are considered VPN egress points. */
  vpnCidrs: string[];
  assets: AssetEntry[];
  /** Usernames that have privileged / admin access. */
  privilegedAccounts: string[];
  ipLocations: IpLocationEntry[];
}

// ─── Top-level result ────────────────────────────────────────────────────────

export interface AnalysisResult {
  events: LogEvent[];
  ingestReport: IngestReport;
  parseReport?: ParseReport;
  alerts: Alert[];
  incidents: Incident[];
  config: Config;
}
